// app/api/uploadthing/core.ts
import { createUploadthing, type FileRouter } from 'uploadthing/next';
import { auth } from '@clerk/nextjs/server'; // or your auth provider

const f = createUploadthing();

export const ourFileRouter = {
  profileImageUploader: f({ image: { maxFileSize: '4MB', maxFileCount: 1 } })
    .middleware(async () => {
      const { userId } = await auth();
      if (!userId) throw new Error('Unauthorized');
      return { userId }; // Passed to onUploadComplete
    })
    .onUploadComplete(async ({ metadata, file }) => {
      console.log('Upload complete for user:', metadata.userId);
      console.log('File URL:', file.url);
      return { uploadedBy: metadata.userId };
    }),
} satisfies FileRouter;

export type OurFileRouter = typeof ourFileRouter;

// components/FileUploader.tsx
'use client';

import { UploadButton } from '@uploadthing/react';
import type { OurFileRouter } from '@/app/api/uploadthing/core';

export function ProfileImageUploader() {
  return (
    <UploadButton<OurFileRouter, 'profileImageUploader'>
      endpoint="profileImageUploader"
      onClientUploadComplete={(res) => {
        console.log('Files:', res);
        alert('Upload complete!');
      }}
      onUploadError={(error: Error) => {
        alert(`Upload error: ${error.message}`);
      }}
    />
  );
}
